INSERT INTO raw_material_properties (raw_material_id, property_key, value_num, value_text, unit, source_version)
SELECT t.id, p.property_key, CAST(p.value_num AS NUMERIC), CAST(p.value_text AS TEXT), CAST(p.unit AS TEXT), '2026-RapidProto'
FROM props p
JOIN src s ON s.material = p.source_name
JOIN LATERAL (
  SELECT rm.id FROM raw_materials rm
  WHERE rm.material = s.material_name
  ORDER BY (rm.material_group = 'Rapid Prototyping') DESC
  LIMIT 1
) t ON true
ON CONFLICT (raw_material_id, property_key) DO NOTHING;

-- ── Roto & Blow Molding: core columns (72 materials, policy suffix)
